-- Cart2Class source-of-truth schema. Execute before policies and seed data.
create extension if not exists pgcrypto;

create type public.app_role as enum ('parent','teacher','store','admin');
create type public.account_status as enum ('active','disabled','invited');
create type public.mission_status as enum ('draft','published','archived');
create type public.sharing_status as enum ('private','submitted','under_review','approved','rejected','featured','archived');
create type public.assignment_status as enum ('scheduled','available','completed','expired','cancelled');
create type public.review_status as enum ('pending','reviewed');
create type public.reward_status as enum ('active','ready','picked_up','completed','cancelled');

create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.schools (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null, address text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, account_status public.account_status not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.role_memberships (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, organization_id uuid not null references public.organizations(id) on delete cascade, role public.app_role not null, is_active boolean not null default true, created_at timestamptz not null default now(), unique(user_id,organization_id,role));
create table public.classes (id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade, name text not null, grade_level smallint not null check (grade_level between 0 and 2), school_year text not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(school_id,name,school_year));
create table public.students (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), school_id uuid not null references public.schools(id), class_id uuid references public.classes(id) on delete set null, first_name text not null, last_initial char(1), grade_level smallint not null check (grade_level between 0 and 2), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.parent_student_relationships (parent_user_id uuid not null references public.profiles(id) on delete cascade, student_id uuid not null references public.students(id) on delete cascade, relationship_label text not null default 'Parent/Guardian', is_active boolean not null default true, created_at timestamptz not null default now(), primary key(parent_user_id,student_id));
create table public.teacher_class_assignments (teacher_user_id uuid not null references public.profiles(id) on delete cascade, class_id uuid not null references public.classes(id) on delete cascade, is_active boolean not null default true, created_at timestamptz not null default now(), primary key(teacher_user_id,class_id));
create table public.stores (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null, contact_email text, address text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.store_memberships (user_id uuid not null references public.profiles(id) on delete cascade, store_id uuid not null references public.stores(id) on delete cascade, is_active boolean not null default true, created_at timestamptz not null default now(), primary key(user_id,store_id));
create table public.student_qr_credentials (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students(id) on delete cascade, token_hash text not null unique, is_active boolean not null default true, expires_at timestamptz, revoked_at timestamptz, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.store_checkin_codes (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id) on delete cascade, token_hash text not null unique, is_active boolean not null default true, expires_at timestamptz, revoked_at timestamptz, created_by uuid references public.profiles(id), created_at timestamptz not null default now());

create table public.missions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), creator_user_id uuid not null references public.profiles(id), title text not null check (char_length(title) between 3 and 140), description text not null default '', grade_min smallint not null check (grade_min between 0 and 2), grade_max smallint not null check (grade_max between grade_min and 2), estimated_minutes smallint not null default 12 check (estimated_minutes between 1 and 60), store_section text, season_tags text[] not null default '{}', status public.mission_status not null default 'draft', sharing_status public.sharing_status not null default 'private', current_version integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.mission_versions (id uuid primary key default gen_random_uuid(), mission_id uuid not null references public.missions(id) on delete cascade, version_number integer not null check (version_number > 0), title text not null, description text not null, learning_objectives text[] not null default '{}', snapshot jsonb not null default '{}'::jsonb, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), unique(mission_id,version_number));
create table public.mission_stages (id uuid primary key default gen_random_uuid(), mission_version_id uuid not null references public.mission_versions(id) on delete cascade, stage_key text not null check (stage_key in ('phonemic_awareness','phonics','fluency','math')), stage_order smallint not null check (stage_order between 1 and 4), title text not null, prompt_text text, audio_path text, unique(mission_version_id,stage_key), unique(mission_version_id,stage_order));
create table public.mission_questions (id uuid primary key default gen_random_uuid(), stage_id uuid not null references public.mission_stages(id) on delete cascade, question_order smallint not null, question_type text not null check (question_type in ('picture_choice','tap_select','sound_recognition','letter_word','reading_prompt','barcode_task','math')), prompt_text text, image_path text, audio_path text, hint_text text, answer_config jsonb not null default '{}'::jsonb, skill_tags text[] not null default '{}', unique(stage_id,question_order));
create table public.mission_answer_options (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.mission_questions(id) on delete cascade, option_order smallint not null, label text, image_path text, is_correct boolean not null default false, unique(question_id,option_order));
create table public.mission_assignments (id uuid primary key default gen_random_uuid(), mission_id uuid not null references public.missions(id), mission_version_id uuid not null references public.mission_versions(id), class_id uuid not null references public.classes(id) on delete cascade, assigned_by uuid not null references public.profiles(id), available_at timestamptz, due_at timestamptz, status public.assignment_status not null default 'scheduled', created_at timestamptz not null default now());
create table public.mission_attempts (id uuid primary key default gen_random_uuid(), client_event_id uuid not null unique, student_id uuid not null references public.students(id), assignment_id uuid references public.mission_assignments(id), mission_version_id uuid not null references public.mission_versions(id), status text not null check (status in ('started','completed','abandoned')), started_at timestamptz not null default now(), completed_at timestamptz, completion_seconds integer check (completion_seconds >= 0), stars_earned integer not null default 0 check (stars_earned >= 0), sync_status text not null default 'synced' check (sync_status in ('pending','synced','failed')));
create table public.mission_responses (id uuid primary key default gen_random_uuid(), client_event_id uuid not null unique, attempt_id uuid not null references public.mission_attempts(id) on delete cascade, question_id uuid not null references public.mission_questions(id), selected_option_id uuid references public.mission_answer_options(id), response_payload jsonb not null default '{}'::jsonb, is_correct boolean, answered_at timestamptz not null default now());
create table public.reading_recordings (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.students(id), attempt_id uuid references public.mission_attempts(id), stage_id uuid references public.mission_stages(id), storage_path text not null unique, upload_status text not null default 'pending' check (upload_status in ('pending','uploaded','failed')), review_status public.review_status not null default 'pending', reviewed_by uuid references public.profiles(id), reviewer_feedback text, recorded_at timestamptz not null default now(), reviewed_at timestamptz);
create table public.products (id uuid primary key default gen_random_uuid(), barcode text unique, name text not null, category text, price numeric(10,2), weight_text text, data_source text, source_checked_at timestamptz, created_at timestamptz not null default now());
create table public.reward_goals (id uuid primary key default gen_random_uuid(), class_id uuid not null references public.classes(id), store_id uuid references public.stores(id), title text not null, description text, target_stars integer not null check (target_stars > 0), current_stars integer not null default 0 check (current_stars >= 0), status public.reward_status not null default 'active', ready_by uuid references public.profiles(id), picked_up_by uuid references public.profiles(id), ready_at timestamptz, picked_up_at timestamptz, created_at timestamptz not null default now());
create table public.reward_events (id uuid primary key default gen_random_uuid(), reward_goal_id uuid not null references public.reward_goals(id) on delete cascade, actor_user_id uuid references public.profiles(id), event_type text not null, note text, created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), recipient_user_id uuid not null references public.profiles(id) on delete cascade, type text not null, title text not null, body text not null, payload jsonb not null default '{}'::jsonb, read_at timestamptz, created_at timestamptz not null default now());
create table public.notification_preferences (user_id uuid primary key references public.profiles(id) on delete cascade, in_app_enabled boolean not null default true, push_enabled boolean not null default false, updated_at timestamptz not null default now());
create table public.mission_favorites (user_id uuid not null references public.profiles(id) on delete cascade, mission_id uuid not null references public.missions(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,mission_id));
create table public.mission_ratings (user_id uuid not null references public.profiles(id) on delete cascade, mission_id uuid not null references public.missions(id) on delete cascade, rating smallint not null check (rating between 1 and 5), comment text, created_at timestamptz not null default now(), primary key(user_id,mission_id));
create table public.mission_flags (id uuid primary key default gen_random_uuid(), mission_id uuid not null references public.missions(id) on delete cascade, reporter_user_id uuid not null references public.profiles(id), reason text not null, status text not null default 'open' check(status in ('open','resolved','dismissed')), created_at timestamptz not null default now());
create table public.sync_events (id uuid primary key default gen_random_uuid(), client_event_id uuid not null unique, student_id uuid not null references public.students(id), event_type text not null, payload jsonb not null default '{}'::jsonb, received_at timestamptz not null default now(), processed_at timestamptz, status text not null default 'received');
create table public.audit_logs (id bigint generated always as identity primary key, organization_id uuid references public.organizations(id), actor_user_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
